  const dialog    = document.getElementById('delete-dialog');
  const nameSpan  = document.getElementById('dialog-image-name');
  const cancelBtn = document.getElementById('btn-cancel');
  const deleteBtn = document.getElementById('btn-delete-confirm');

  let activeTrigger = null; // the button that opened the dialog

  /* ── Open dialog ──────────────────────────────────────────── */
  document.addEventListener('click', (e) => {
    const trigger = e.target.closest('.trigger[data-image-name]');
    if (!trigger) return;

    activeTrigger = trigger;
    nameSpan.textContent = trigger.dataset.imageName;
    dialog.showModal();

    // Move focus to the cancel button (safe default — avoids accidental delete)
    cancelBtn.focus();
  });

  /* ── Close helpers ────────────────────────────────────────── */
  function closeDialog() {
    dialog.close();
    activeTrigger?.focus(); // restore focus to the triggering button
    activeTrigger = null;
  }

  cancelBtn.addEventListener('click', closeDialog);

  /* Close when clicking the native backdrop */
  dialog.addEventListener('click', (e) => {
    if (e.target === dialog) closeDialog();
  });

  /* Escape is handled natively by <dialog>; restore focus after */
  dialog.addEventListener('close', () => {
    activeTrigger?.focus();
    activeTrigger = null;
  });

  /* ── Confirm delete ───────────────────────────────────────── */
  deleteBtn.addEventListener('click', () => {
    const cardToRemove = activeTrigger?.closest('.card');

    // Announce removal to screen readers before closing
    const liveRegion = document.getElementById('sr-live');
    liveRegion.textContent = `"${nameSpan.textContent}" has been deleted.`;

    closeDialog();

    if (cardToRemove) {
      // Brief fade-out, then remove from DOM
      cardToRemove.style.transition = 'opacity 250ms ease, transform 250ms ease';
      cardToRemove.style.opacity    = '0';
      cardToRemove.style.transform  = 'scale(.96)';
      setTimeout(() => cardToRemove.remove(), 270);
    }
  });
})();
