+/* ── Reset & Tokens ─────────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --color-bg:           #f5f5f7;
+  --color-surface:      #ffffff;
+  --color-surface-2:    #f0f0f2;
+  --color-border:       #d1d1d6;
+  --color-text:         #1d1d1f;
+  --color-text-subtle:  #6e6e73;
+  --color-primary:      #0071e3;
+  --color-primary-hover:#0077ed;
+  --color-primary-fg:   #ffffff;
+  --color-danger:       #c0392b;
+  --color-danger-hover: #a93226;
+  --color-danger-fg:    #ffffff;
+  --color-overlay:      rgba(0, 0, 0, 0.45);
+
+  --radius-sm:  6px;
+  --radius-md:  12px;
+  --radius-lg:  18px;
+
+  --shadow-card:   0 1px 4px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
+  --shadow-dialog: 0 8px 40px rgba(0,0,0,.22);
+
+  --transition: 180ms ease;
+}
+
+/* ── Base ───────────────────────────────────────────────────── */
+body {
+  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
+  background: var(--color-bg);
+  color: var(--color-text);
+  line-height: 1.5;
+  min-height: 100vh;
+}
+
+/* ── Skip link ──────────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 1rem;
+  z-index: 9999;
+  padding: .5rem 1rem;
+  background: var(--color-primary);
+  color: var(--color-primary-fg);
+  border-radius: var(--radius-sm);
+  font-size: .875rem;
+  font-weight: 600;
+  text-decoration: none;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; }
+
+/* ── Site header ────────────────────────────────────────────── */
+.site-header {
+  background: rgba(255,255,255,.85);
+  backdrop-filter: saturate(180%) blur(20px);
+  border-bottom: 1px solid var(--color-border);
+  position: sticky;
+  top: 0;
+  z-index: 100;
+}
+.site-header__inner {
+  max-width: 1100px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+  height: 56px;
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.site-header__logo {
+  font-size: 1.1rem;
+  font-weight: 700;
+  color: var(--color-text);
+  text-decoration: none;
+  letter-spacing: -.02em;
+}
+.site-header__nav {
+  margin-left: auto;
+  display: flex;
+  gap: .25rem;
+}
+.site-header__nav a {
+  padding: .375rem .75rem;
+  border-radius: var(--radius-sm);
+  font-size: .9rem;
+  color: var(--color-text-subtle);
+  text-decoration: none;
+  transition: background var(--transition), color var(--transition);
+}
+.site-header__nav a:hover  { background: var(--color-surface-2); color: var(--color-text); }
+.site-header__nav a:focus-visible {
+  outline: 2px solid var(--color-primary);
+  outline-offset: 2px;
+}
+
+/* ── Main layout ────────────────────────────────────────────── */
+main {
+  max-width: 1100px;
+  margin: 0 auto;
+  padding: 2.5rem 1.5rem 4rem;
+}
+
+.page-header {
+  margin-bottom: 2rem;
+}
+.page-header h1 {
+  font-size: 1.75rem;
+  font-weight: 700;
+  letter-spacing: -.03em;
+}
+.page-header p {
+  margin-top: .375rem;
+  color: var(--color-text-subtle);
+  font-size: .95rem;
+}
+
+/* ── Gallery grid ───────────────────────────────────────────── */
+.gallery {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.25rem;
+}
+
+/* ── Image card ─────────────────────────────────────────────── */
+.card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-card);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.card:hover {
+  box-shadow: 0 4px 20px rgba(0,0,0,.12);
+  transform: translateY(-2px);
+}
+.card__image-wrap {
+  aspect-ratio: 4 / 3;
+  overflow: hidden;
+  background: var(--color-surface-2);
+}
+.card__image-wrap img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  display: block;
+  transition: transform 300ms ease;
+}
+.card:hover .card__image-wrap img { transform: scale(1.04); }
+
+.card__body {
+  padding: 1rem 1rem .875rem;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+  flex: 1;
+}
+.card__title {
+  font-size: .9rem;
+  font-weight: 600;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.card__meta {
+  font-size: .8rem;
+  color: var(--color-text-subtle);
+}
+
+/* ── Card actions ───────────────────────────────────────────── */
+.card__actions {
+  display: flex;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .5rem;
+  border-top: 1px solid var(--color-surface-2);
+}
+
+/* ── Shared button base ─────────────────────────────────────── */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: .375rem;
+  padding: .45rem .875rem;
+  border: 1px solid transparent;
+  border-radius: var(--radius-sm);
+  font-size: .825rem;
+  font-weight: 600;
+  cursor: pointer;
+  text-decoration: none;
+  transition: background var(--transition), color var(--transition),
+              border-color var(--transition), box-shadow var(--transition);
+  white-space: nowrap;
+}
+.btn:focus-visible {
+  outline: 2px solid var(--color-primary);
+  outline-offset: 2px;
+}
+.btn:disabled { opacity: .45; cursor: not-allowed; }
+
+.btn--ghost {
+  background: transparent;
+  color: var(--color-text-subtle);
+  border-color: var(--color-border);
+}
+.btn--ghost:hover:not(:disabled) {
+  background: var(--color-surface-2);
+  color: var(--color-text);
+}
+
+.btn--danger {
+  background: transparent;
+  color: var(--color-danger);
+  border-color: var(--color-danger);
+}
+.btn--danger:hover:not(:disabled) {
+  background: var(--color-danger);
+  color: var(--color-danger-fg);
+}
+.btn--danger:focus-visible {
+  outline-color: var(--color-danger);
+}
+
+.btn--primary {
+  background: var(--color-primary);
+  color: var(--color-primary-fg);
+  border-color: var(--color-primary);
+}
+.btn--primary:hover:not(:disabled) {
+  background: var(--color-primary-hover);
+  border-color: var(--color-primary-hover);
+}
+
+.btn--danger-solid {
+  background: var(--color-danger);
+  color: var(--color-danger-fg);
+  border-color: var(--color-danger);
+}
+.btn--danger-solid:hover:not(:disabled) {
+  background: var(--color-danger-hover);
+  border-color: var(--color-danger-hover);
+}
+.btn--danger-solid:focus-visible {
+  outline-color: var(--color-danger);
+}
+
+/* ── Dialog (native <dialog>) ───────────────────────────────── */
+.dialog-backdrop {
+  /* <dialog>::backdrop is used for the native overlay, but we also style
+     the dialog itself for centering */
+}
+dialog {
+  padding: 0;
+  border: none;
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-dialog);
+  background: var(--color-surface);
+  max-width: min(420px, calc(100vw - 2rem));
+  width: 100%;
+  /* centering in older browsers that don't auto-center <dialog> */
+  margin: auto;
+}
+dialog::backdrop {
+  background: var(--color-overlay);
+  backdrop-filter: blur(3px);
+}
+/* animate open */
+@keyframes dialog-in {
+  from { opacity: 0; transform: scale(.95) translateY(6px); }
+  to   { opacity: 1; transform: scale(1)  translateY(0);    }
+}
+dialog[open] { animation: dialog-in 200ms ease forwards; }
+
+.dialog__header {
+  display: flex;
+  align-items: flex-start;
+  gap: .875rem;
+  padding: 1.5rem 1.5rem 1rem;
+}
+.dialog__icon {
+  flex-shrink: 0;
+  width: 40px;
+  height: 40px;
+  border-radius: 50%;
+  background: #fdecea;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.dialog__icon svg { color: var(--color-danger); }
+
+.dialog__title {
+  font-size: 1.05rem;
+  font-weight: 700;
+  letter-spacing: -.02em;
+  line-height: 1.3;
+  padding-top: .35rem; /* align with icon center */
+}
+
+.dialog__body {
+  padding: 0 1.5rem 1.5rem;
+}
+.dialog__description {
+  font-size: .9rem;
+  color: var(--color-text-subtle);
+  line-height: 1.6;
+}
+.dialog__image-name {
+  font-weight: 600;
+  color: var(--color-text);
+}
+
+.dialog__footer {
+  display: flex;
+  justify-content: flex-end;
+  gap: .625rem;
+  padding: 1rem 1.5rem 1.25rem;
+  border-top: 1px solid var(--color-border);
+}
+
+/* ── Forced colors ──────────────────────────────────────────── */
+@media (forced-colors: active) {
